def list_transactions(self, params: dict) -> tuple[int, dict]:
    """GET /v1/index/transactions — paginated confirmed-chain tx index.

    Pending-tip transactions are excluded. Filters (AND-combined):
    ``tx_id`` (64 lowercase hex), ``account`` (matches sender or
    recipient), ``height``, the inclusive ``min_height``/``max_height``
    range (an exact ``height`` intersects with the range) and
    ``direction`` (``all`` keeps the sender-or-recipient account match,
    ``out`` matches senders only, ``in`` recipients only; ``in``/``out``
    require a non-empty ``account``); ``limit`` (default 50, range
    1-200) and ``cursor`` (default 0) paginate. Numeric filters must be
    plain decimals without leading zeros; any malformed value returns
    400. The range/direction parameters accept ASCII digits only and
    every violation of their rules — empty values, malformed heights,
    inverted bounds, an unknown direction, a missing account for
    ``in``/``out`` — returns the fixed ``400 {"error": "input"}``.
    Rows are ordered by (height, index, tx_id); ``index`` is the
    transaction's 0-based position inside its block, matching the Merkle
    proof index. A cursor beyond the filtered total returns 400, a cursor
    equal to it returns an empty page.

    The optional anchor pair ``at_height``/``at_hash`` fixes the query
    prefix to the confirmed main-chain blocks from genesis through the
    anchor block inclusive. The parameters are all-or-nothing: exactly
    one of them, an empty value, a malformed value (an ASCII
    non-negative decimal without leading zeros; a 64-char lowercase hex
    string) or a repeated occurrence returns the fixed
    ``400 {"error": "input"}``. With both present, an unknown anchor
    height (or one naming the pending tip) returns 404
    ``anchor_not_found`` and a confirmed block with a different hash
    returns 409 ``anchor_conflict``; candidate forks never satisfy an
    anchor. Anchor errors take precedence over the cursor-out-of-range
    check. With a valid prefix, the other filters still intersect it and
    ``total``/``next_cursor`` count only the fixed prefix, so pages
    taken under the same anchor stay identical as the chain tail grows
    or is rolled back.

    The optional ``include_summary`` accepts a single occurrence of
    ``true``/``false``; omitted or ``false`` the response is unchanged.
    An empty value, any other token (or a repeat, rejected at the HTTP
    layer) returns the fixed ``400 {"error": "input"}``. When ``true``
    a non-empty ``account`` is required (else the same fixed input
    error, answered before the anchor lookup) and the response adds
    ``summary`` with ``incoming_count``/``outgoing_count`` (the number
    of filtered transactions received/sent by the account),
    ``incoming_amount``/``outgoing_amount`` (the matching integer
    sums) and ``net_amount`` (incoming minus outgoing, may be
    negative). The summary spans the whole filtered confirmed set, not
    just the current page; a self-transfer occupies one row but adds
    one to both counts/amounts and zero to the net. An empty page at
    ``cursor == total`` still carries the full summary. All figures
    are integers.
    """
    tx_id = params.get("tx_id")
    if tx_id is not None and not crypto.is_hex64(tx_id):
        return 400, {"error": "tx_id must be 64 lowercase hex characters"}

    # include_summary is a strict single-occurrence true/false flag (the
    # repeat check lives in the HTTP layer). Every violation — empty
    # value, unknown token — maps to the contract-fixed
    # {"error": "input"} and is answered before the anchor is looked up.
    include_summary_raw = params.get("include_summary")
    if include_summary_raw is not None and include_summary_raw not in (
        "true",
        "false",
    ):
        return 400, {"error": "input"}
    include_summary = include_summary_raw == "true"

    # Anchor pair: all-or-nothing with strict formats. Every violation
    # maps to the contract-fixed {"error": "input"} and is answered
    # before any state is read.
    at_height_raw = params.get("at_height")
    at_hash = params.get("at_hash")
    anchor_present = at_height_raw is not None or at_hash is not None
    if anchor_present:
        if at_height_raw is None or at_hash is None:
            return 400, {"error": "input"}
        at_height = _parse_ascii_decimal(at_height_raw)
        if at_height is None or not crypto.is_hex64(at_hash):
            return 400, {"error": "input"}
    else:
        at_height = None

    # The range/direction parameters validate first so that every one of
    # their violations maps to the contract-fixed {"error": "input"} —
    # including ``in``/``out`` with an empty account, which would
    # otherwise fall into the legacy account message below.
    min_height = None
    if params.get("min_height") is not None:
        min_height = _parse_ascii_decimal(params["min_height"])
        if min_height is None:
            return 400, {"error": "input"}
    max_height = None
    if params.get("max_height") is not None:
        max_height = _parse_ascii_decimal(params["max_height"])
        if max_height is None:
            return 400, {"error": "input"}
    if (
        min_height is not None
        and max_height is not None
        and min_height > max_height
    ):
        return 400, {"error": "input"}
    direction = params.get("direction")
    if direction is None:
        direction = "all"
    elif direction not in ("all", "in", "out"):
        return 400, {"error": "input"}
    if direction in ("in", "out"):
        required_account = params.get("account")
        if not isinstance(required_account, str) or not required_account:
            return 400, {"error": "input"}

    account = params.get("account")
    # The summary is computed per account, so enabling it without a valid
    # account is the fixed input error; check it before the legacy account
    # message (which uses a different error body).
    if include_summary and not (
        isinstance(account, str) and account
    ):
        return 400, {"error": "input"}
    if account is not None and (not isinstance(account, str) or not account):
        return 400, {"error": "account must be a non-empty string"}

    height = None
    if params.get("height") is not None:
        height = _parse_decimal(params["height"])
        if height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    limit = self.INDEX_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.INDEX_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        # Resolve the anchor against the persisted main chain inside
        # the same lock that builds the rows, so the anchor decision,
        # the entries and the pagination share one chain snapshot;
        # candidate forks are never consulted.
        if anchor_present:
            anchor_block = self.store.block_at(at_height)
            if (
                anchor_block is None
                or anchor_block.status != STATUS_CONFIRMED
            ):
                return 404, {"error": "anchor_not_found"}
            if anchor_block.block_hash != at_hash:
                return 409, {"error": "anchor_conflict"}
        rows: list[dict] = []
        for block in self.store.chain:
            if block.status != STATUS_CONFIRMED:
                continue
            if at_height is not None and block.height > at_height:
                break
            if height is not None and block.height != height:
                continue
            if min_height is not None and block.height < min_height:
                continue
            if max_height is not None and block.height > max_height:
                continue
            for index, tx in enumerate(block.transactions):
                if tx_id is not None and tx.tx_id != tx_id:
                    continue
                if account is not None:
                    # A self-transfer matches every direction and is
                    # listed once, since each transaction is tested once.
                    if direction == "out":
                        if tx.sender != account:
                            continue
                    elif direction == "in":
                        if tx.recipient != account:
                            continue
                    elif account not in (tx.sender, tx.recipient):
                        continue
                rows.append(
                    {
                        "tx_id": tx.tx_id,
                        "height": block.height,
                        "block_hash": block.block_hash,
                        "index": index,
                        "from": tx.sender,
                        "to": tx.recipient,
                        "amount": tx.amount,
                    }
                )
    # Chain order is already (height, index) ascending; the tx_id
    # tiebreaker is implied because ids are unique within a block.
    total = len(rows)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    items = rows[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    body: dict = {"items": items, "total": total, "next_cursor": next_cursor}
    if include_summary:
        # The summary covers the WHOLE filtered set (all confirmed rows
        # collected above), never just the current page. Direction filters
        # transactions first; each surviving row is then re-classified by
        # the account independently, so a self-transfer counts once as
        # incoming and once as outgoing while occupying a single total.
        # All arithmetic stays on Python integers.
        incoming_count = 0
        outgoing_count = 0
        incoming_amount = 0
        outgoing_amount = 0
        for row in rows:
            if row["to"] == account:
                incoming_count += 1
                incoming_amount += row["amount"]
            if row["from"] == account:
                outgoing_count += 1
                outgoing_amount += row["amount"]
        body["summary"] = {
            "incoming_count": incoming_count,
            "outgoing_count": outgoing_count,
            "incoming_amount": incoming_amount,
            "outgoing_amount": outgoing_amount,
            "net_amount": incoming_amount - outgoing_amount,
        }
    return 200, body

